// buildSessionReportRequestUsarNoTrigger creates SessionReportRequest with:
// - ReportType.Usar=true (0x02)
// - UsageReport IE with URRID and VolumeMeasurement but WITHOUT UsageReportTrigger
func buildSessionReportRequestUsarNoTrigger(seid uint64, seq uint32) []byte {
	// ReportType IE with USAR flag set.
	reportTypeIE := []byte{
		0x00, 0x27, // Type = 39 (ReportType)
		0x00, 0x01, // Length = 1
		0x02,       // Flags: USAR=1
	}

	// URRID IE.
	urridIE := []byte{
		0x00, 0x51, // Type = 81 (URR-ID)
		0x00, 0x04, // Length = 4
		0x00, 0x00, 0x00, 0x01, // URR ID = 1
	}

	// VolumeMeasurement IE with only volume fields present (flags=0x07).
	volumeMeasurementIE := []byte{
		0x00, 0x42, // Type = 66 (VolumeMeasurement)
		0x00, 0x19, // Length = 25
		0x07,       // Flags: TOVOL/ULVOL/DLVOL present
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10, 0x00, // Total Volume = 4096
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x00, // Uplink Volume = 2048
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x00, // Downlink Volume = 2048
	}

	// UsageReportTrigger IE is intentionally omitted.
	usageReportContent := append(urridIE, volumeMeasurementIE...)
	usageReportLen := uint16(len(usageReportContent))

	usageReportIE := []byte{
		0x00, 0x50, // Type = 80 (UsageReport for SessionReportRequest)
		byte(usageReportLen >> 8), byte(usageReportLen), // Length
	}
	usageReportIE = append(usageReportIE, usageReportContent...)

	allIEs := append(reportTypeIE, usageReportIE...)

	msgLen := uint16(12 + len(allIEs))
	header := make([]byte, 16)
	header[0] = 0x21                               // Version=1, S=1
	header[1] = 56                                 // Message Type = SessionReportRequest
	binary.BigEndian.PutUint16(header[2:4], msgLen)
	binary.BigEndian.PutUint64(header[4:12], seid)
	header[12] = byte(seq >> 16)
	header[13] = byte(seq >> 8)
	header[14] = byte(seq)
	header[15] = 0x00

	return append(header, allIEs...)
}

func waitSessionReportResponse(conn *net.UDPConn, timeout time.Duration) (*message.SessionReportResponse, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 2048)

	for {
		conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return nil, err
		}

		msg, err := message.Parse(buf[:n])
		if err != nil {
			continue
		}

		if rsp, ok := msg.(*message.SessionReportResponse); ok {
			return rsp, nil
		}
	}
}

func sessionReportCause(rsp *message.SessionReportResponse) (uint8, bool) {
	if rsp == nil || rsp.Cause == nil {
		return 0, false
	}

	cause, err := rsp.Cause.Cause()
	if err != nil {
		return 0, false
	}

	return cause, true
}

