func establishAssociation(conn *net.UDPConn, nodeID string) bool {
	req := message.NewAssociationSetupRequest(
		1,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)

	payload, err := req.Marshal()
	if err != nil {
		log.Printf("[-] Failed to marshal AssociationSetupRequest: %v", err)
		return false
	}

	log.Printf("[*] Sending AssociationSetupRequest...")
	_, err = conn.Write(payload)
	if err != nil {
		log.Printf("[-] Failed to send AssociationSetupRequest: %v", err)
		return false
	}

	conn.SetReadDeadline(time.Now().Add(5 * time.Second))
	buf := make([]byte, 2048)
	n, err := conn.Read(buf)
	if err != nil {
		log.Printf("[-] No AssociationSetupResponse received: %v", err)
		return false
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		log.Printf("[-] Failed to parse AssociationSetupResponse: %v", err)
		return false
	}

	if msg.MessageType() == message.MsgTypeAssociationSetupResponse {
		log.Printf("[+] Received AssociationSetupResponse")
		return true
	}

	log.Printf("[-] Unexpected response type: %d", msg.MessageType())
	return false
}

func sendAssociationSetupRequest(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	req := message.NewAssociationSetupRequest(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := req.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendAssociationSetupResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	rsp := message.NewAssociationSetupResponse(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendSessionEstablishmentResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID, upfIP string, cpSeid uint64, seq uint32) error {
	v4 := net.ParseIP(upfIP)
	if v4 != nil {
		v4 = v4.To4()
	}
	if v4 == nil {
		v4 = net.ParseIP(nodeID)
		if v4 != nil {
			v4 = v4.To4()
		}
	}

	ies := []*ie.IE{
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
	}
	if v4 != nil {
		if fseid := ie.NewFSEID(cpSeid, v4, nil); fseid != nil {
			ies = append(ies, fseid)
		}
	} else {
		log.Printf("[-] Unable to parse UPF IPv4 from listenIP=%q nodeID=%q; sending response without F-SEID", upfIP, nodeID)
	}

	rsp := message.NewSessionEstablishmentResponse(
		0,
		0,
		cpSeid,
		seq,
		0,
		ies...,
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendSessionModificationResponse(conn *net.UDPConn, raddr *net.UDPAddr, seid uint64, seq uint32) error {
	rsp := message.NewSessionModificationResponse(
		0,
		0,
		seid,
		seq,
		0,
		ie.NewCause(ie.CauseRequestAccepted),
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func hasBufferedUpdateFAR(req *message.SessionModificationRequest) bool {
	if req == nil {
		return false
	}
	for _, farIE := range req.UpdateFAR {
		if farIE == nil {
			continue
		}
		if farIE.HasBUFF() {
			return true
		}
	}
	return false
}

func sendHeartbeatResponse(conn *net.UDPConn, raddr *net.UDPAddr, seq uint32) error {
	rsp := message.NewHeartbeatResponse(seq, ie.NewRecoveryTimeStamp(time.Now()))
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func cpfSeidFromSessionEstablishment(req *message.SessionEstablishmentRequest) (uint64, *ie.FSEIDFields, bool) {
	if req == nil || req.CPFSEID == nil {
		return 0, nil, false
	}
	fseid, err := req.CPFSEID.FSEID()
	if err != nil {
		return 0, nil, false
	}
	return fseid.SEID, fseid, true
}

func nodeIDFromIE(nodeIE *ie.IE) string {
	if nodeIE == nil {
		return "unknown"
	}
	nodeID, err := nodeIE.NodeID()
	if err != nil {
		return "unknown"
	}
	return nodeID
}

func ipString(ip net.IP) string {
	if ip == nil {
		return "-"
	}
	return ip.String()
}

// buildSessionReportRequestUsarNoUrrid creates SessionReportRequest with:
// - ReportType.Usar=true (0x02)
// - UsageReport IE with VolumeMeasurement but WITHOUT URRID sub-IE
func buildSessionReportRequestUsarNoUrrid(seid uint64, seq uint32) []byte {
	// Create ReportType IE with USAR flag set
	// ReportType IE: Type=39, Length=1, Flags byte
	// USAR flag is bit 1 (0x02)
	reportTypeIE := []byte{
		0x00, 0x27, // Type = 39 (ReportType)
		0x00, 0x01, // Length = 1
		0x02,       // Flags: USAR=1 (bit 1)
	}

	// Create VolumeMeasurement IE (include this but omit URRID)
	// VolumeMeasurement IE: Type=66
	volumeMeasurementIE := []byte{
		0x00, 0x42, // Type = 66 (VolumeMeasurement)
		0x00, 0x19, // Length = 25
		0x07,       // Flags: All volume fields present
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x10, 0x00, // Total Volume = 4096
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x00, // Uplink Volume = 2048
		0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x08, 0x00, // Downlink Volume = 2048
	}

	// UsageReportTrigger IE: Type=63
	usageReportTriggerIE := []byte{
		0x00, 0x3F, // Type = 63 (UsageReportTrigger)
		0x00, 0x03, // Length = 3
		0x00, 0x00, 0x01, // VOLTH flag set
	}

	// Build UsageReport grouped IE - deliberately OMIT URRID
	usageReportContent := append(volumeMeasurementIE, usageReportTriggerIE...)
	usageReportLen := uint16(len(usageReportContent))

	usageReportIE := []byte{
		0x00, 0x50, // Type = 80 (UsageReport for SessionReportRequest)
		byte(usageReportLen >> 8), byte(usageReportLen), // Length
	}
	usageReportIE = append(usageReportIE, usageReportContent...)

	// Combine IEs
	allIEs := append(reportTypeIE, usageReportIE...)

	// PFCP Header for session-related message
	msgLen := uint16(12 + len(allIEs)) // 12 bytes after length field + IEs
	header := make([]byte, 16)
	header[0] = 0x21                               // Version=1, S=1
	header[1] = 56                                 // Message Type = SessionReportRequest
	binary.BigEndian.PutUint16(header[2:4], msgLen)
	binary.BigEndian.PutUint64(header[4:12], seid)
	header[12] = byte(seq >> 16)
	header[13] = byte(seq >> 8)
	header[14] = byte(seq)
	header[15] = 0x00

	// Combine header and IEs
	msg := append(header, allIEs...)
	return msg
}

func waitSessionReportResponse(conn *net.UDPConn, timeout time.Duration) (*message.SessionReportResponse, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 2048)

	for {
		conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return nil, err
		}

		msg, err := message.Parse(buf[:n])
		if err != nil {
			continue
		}

		if rsp, ok := msg.(*message.SessionReportResponse); ok {
			return rsp, nil
		}
	}
}

func sessionReportCause(rsp *message.SessionReportResponse) (uint8, bool) {
	if rsp == nil || rsp.Cause == nil {
		return 0, false
	}

	cause, err := rsp.Cause.Cause()
	if err != nil {
		return 0, false
	}

	return cause, true
}

func probeSmf(conn *net.UDPConn) {
	log.Printf("[*] Sending HeartbeatRequest probe...")

	req := message.NewHeartbeatRequest(
		0x1234,
		ie.NewRecoveryTimeStamp(time.Now()),
		nil,
	)
	payload, _ := req.Marshal()

	conn.SetReadDeadline(time.Now().Add(3 * time.Second))
