func sendAssociationSetupRequest(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	req := message.NewAssociationSetupRequest(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := req.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendAssociationSetupResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID string, seq uint32) error {
	rsp := message.NewAssociationSetupResponse(
		seq,
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
		ie.NewRecoveryTimeStamp(time.Now()),
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendSessionEstablishmentResponse(conn *net.UDPConn, raddr *net.UDPAddr, nodeID, upfIP string, cpSeid uint64, seq uint32) error {
	v4 := net.ParseIP(upfIP)
	if v4 != nil {
		v4 = v4.To4()
	}
	if v4 == nil {
		v4 = net.ParseIP(nodeID)
		if v4 != nil {
			v4 = v4.To4()
		}
	}

	ies := []*ie.IE{
		ie.NewNodeIDHeuristic(nodeID),
		ie.NewCause(ie.CauseRequestAccepted),
	}
	if v4 != nil {
		if fseid := ie.NewFSEID(cpSeid, v4, nil); fseid != nil {
			ies = append(ies, fseid)
		}
	} else {
		log.Printf("[-] Unable to parse UPF IPv4 from listenIP=%q nodeID=%q; sending response without F-SEID", upfIP, nodeID)
	}

	rsp := message.NewSessionEstablishmentResponse(
		0,
		0,
		cpSeid,
		seq,
		0,
		ies...,
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func sendSessionModificationResponse(conn *net.UDPConn, raddr *net.UDPAddr, seid uint64, seq uint32) error {
	rsp := message.NewSessionModificationResponse(
		0,
		0,
		seid,
		seq,
		0,
		ie.NewCause(ie.CauseRequestAccepted),
	)
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func hasBufferedUpdateFAR(req *message.SessionModificationRequest) bool {
	if req == nil {
		return false
	}
	for _, farIE := range req.UpdateFAR {
		if farIE == nil {
			continue
		}
		if farIE.HasBUFF() {
			return true
		}
	}
	return false
}

func sendHeartbeatResponse(conn *net.UDPConn, raddr *net.UDPAddr, seq uint32) error {
	rsp := message.NewHeartbeatResponse(seq, ie.NewRecoveryTimeStamp(time.Now()))
	payload, err := rsp.Marshal()
	if err != nil {
		return err
	}
	_, err = conn.WriteToUDP(payload, raddr)
	return err
}

func cpfSeidFromSessionEstablishment(req *message.SessionEstablishmentRequest) (uint64, *ie.FSEIDFields, bool) {
	if req == nil || req.CPFSEID == nil {
		return 0, nil, false
	}
	fseid, err := req.CPFSEID.FSEID()
	if err != nil {
		return 0, nil, false
	}
	return fseid.SEID, fseid, true
}

func nodeIDFromIE(nodeIE *ie.IE) string {
	if nodeIE == nil {
		return "unknown"
	}
	nodeID, err := nodeIE.NodeID()
	if err != nil {
		return "unknown"
	}
	return nodeID
}

func ipString(ip net.IP) string {
	if ip == nil {
		return "-"
	}
	return ip.String()
}

// buildSessionReportRequestDldrNoReport creates SessionReportRequest with
// ReportType.Dldr=true but WITHOUT DownlinkDataReport IE
func buildSessionReportRequestDldrNoReport(seid uint64, seq uint32) []byte {
	// Create ReportType IE with DLDR flag set
	// ReportType IE: Type=39, Length=1, Flags byte
	// DLDR flag is bit 0 (0x01)
	reportTypeIE := []byte{
		0x00, 0x27, // Type = 39 (ReportType)
		0x00, 0x01, // Length = 1
		0x01, // Flags: DLDR=1
	}

	// PFCP Header for session-related message
	msgLen := uint16(12 + len(reportTypeIE)) // 12 bytes after length field + IEs
	header := make([]byte, 16)
	header[0] = 0x21                               // Version=1, S=1
	header[1] = 56                                 // Message Type = SessionReportRequest
	binary.BigEndian.PutUint16(header[2:4], msgLen)
	binary.BigEndian.PutUint64(header[4:12], seid)
	header[12] = byte(seq >> 16)
	header[13] = byte(seq >> 8)
	header[14] = byte(seq)
	header[15] = 0x00

	// Combine header and ReportType IE (deliberately omitting DownlinkDataReport)
	msg := append(header, reportTypeIE...)
	return msg
}

